import{_ as e,c as s,a2 as i,o as l}from"./chunks/framework.BnrAgU0Y.js";const g=JSON.parse('{"title":"贡献于 Langflow","description":"贡献于 Langflow","frontmatter":{"title":"贡献于 Langflow","description":"贡献于 Langflow","layout":"doc"},"headers":[],"relativePath":"langflow/contributing-how-to-contribute.md","filePath":"langflow/contributing-how-to-contribute.md"}'),n={name:"langflow/contributing-how-to-contribute.md"};function t(r,a,o,h,d,p){return l(),s("div",null,a[0]||(a[0]=[i(`<h1 id="贡献于-langflow" tabindex="-1">贡献于 Langflow <a class="header-anchor" href="#贡献于-langflow" aria-label="Permalink to &quot;贡献于 Langflow&quot;">​</a></h1><p>本指南旨在帮助您开始为 Langflow 做出贡献。作为一个在快速发展领域的开源项目，Langflow 欢迎各类贡献，无论是新特性的开发、基础设施的改进，还是文档的完善。</p><p>要为此项目贡献代码或文档，请遵循 <a href="https://docs.github.com/en/get-started/quickstart/contributing-to-projects" target="_blank" rel="noreferrer">fork 和 pull request</a> 工作流程。</p><h2 id="贡献代码" tabindex="-1">贡献代码 <a class="header-anchor" href="#贡献代码" aria-label="Permalink to &quot;贡献代码&quot;">​</a></h2><p>本地开发 Langflow 使用 <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv</a> 和 <a href="https://nodejs.org/en/download/package-manager" target="_blank" rel="noreferrer">Node.js</a>。</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv（&gt;=0.4）</a></li><li><a href="https://nodejs.org/en/download/package-manager" target="_blank" rel="noreferrer">Node.js</a></li></ul><h3 id="克隆-langflow-仓库" tabindex="-1">克隆 Langflow 仓库 <a class="header-anchor" href="#克隆-langflow-仓库" aria-label="Permalink to &quot;克隆 Langflow 仓库&quot;">​</a></h3><ol><li><p>进入 <a href="https://github.com/langflow-ai/langflow" target="_blank" rel="noreferrer">Langflow GitHub 仓库</a>，然后点击 <strong>Fork</strong>（派生）。</p></li><li><p>将新的远程仓库添加到本地计算机上的本地仓库：</p></li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fork</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_git_usernam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/langflow.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="准备开发环境" tabindex="-1">准备开发环境 <a class="header-anchor" href="#准备开发环境" aria-label="Permalink to &quot;准备开发环境&quot;">​</a></h3><ol><li><p>创建开发钩子。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>此命令通过安装后端和前端依赖项、构建前端静态文件以及初始化项目来设置开发环境。它依次运行 <code>make install_backend</code>、<code>make install_frontend</code>、<code>make build_frontend</code>，最后运行 <code>uv run langflow run</code> 来启动应用程序。</p></li><li><p>在提交到代码库之前，运行 <code>make lint</code>、<code>make format</code> 和 <code>make unit_tests</code>。</p></li></ol><h3 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h3><p>这个仓库包含一个用于在 VSCode 中调试后端的 <code>.vscode/launch.json</code> 文件，这比使用 Docker Compose 进行调试速度更快。要在 VSCode 中使用 <code>launch.json</code> 文件调试 Langflow：</p><ol><li>在 VSCode 中打开 Langflow。</li><li>按 <strong>Ctrl+Shift+D</strong>（Windows）或 <strong>Cmd+Shift+D</strong>（Mac）打开运行和调试视图。</li><li>从 <strong>运行和调试</strong> 下拉菜单中，选择一个调试配置。</li><li>点击绿色 <strong>播放</strong> 按钮或按 F5 开始调试。</li></ol><p>使用 <code>launch.json</code> 可以在 VSCode 中快速调试应用程序的不同部分，比如后端、前端或 CLI。</p><h3 id="本地运行-langflow" tabindex="-1">本地运行 Langflow <a class="header-anchor" href="#本地运行-langflow" aria-label="Permalink to &quot;本地运行 Langflow&quot;">​</a></h3><p>在通过 <code>make init</code> 设置好环境后，您可以分别运行 Langflow 的后台和前台以进行开发。Langflow 推荐使用像 <a href="https://docs.python.org/3/library/venv.html" target="_blank" rel="noreferrer">venv</a> 或 <a href="https://anaconda.org/anaconda/conda" target="_blank" rel="noreferrer">conda</a> 这样的虚拟环境来隔离依赖。</p><p>在开始之前，请确保您已安装 <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv</a> 和 <a href="https://nodejs.org/en/download/package-manager" target="_blank" rel="noreferrer">Node.js</a>。</p><ol><li><p>在仓库根目录中，安装依赖并启动开发服务器以运行后台：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>安装依赖并启动前台：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><p>这种方法允许您独立于前后台进行开发，并通过热重载（hot-reloading）加快开发速度。</p><h2 id="贡献文档" tabindex="-1">贡献文档 <a class="header-anchor" href="#贡献文档" aria-label="Permalink to &quot;贡献文档&quot;">​</a></h2><p>本文档使用 <a href="https://docusaurus.io/" target="_blank" rel="noreferrer">Docusaurus</a> 构建，并采用 <a href="https://docusaurus.io/docs/markdown-features" target="_blank" rel="noreferrer">Markdown</a> 编写。</p><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h3><ul><li><a href="https://nodejs.org/en/download/package-manager" target="_blank" rel="noreferrer">Node.js</a></li></ul><h3 id="克隆-langflow-仓库-1" tabindex="-1">克隆 Langflow 仓库 <a class="header-anchor" href="#克隆-langflow-仓库-1" aria-label="Permalink to &quot;克隆 Langflow 仓库&quot;">​</a></h3><ol><li><p>访问 <a href="https://github.com/langflow-ai/langflow" target="_blank" rel="noreferrer">Langflow GitHub 仓库</a>，然后点击 <strong>Fork</strong>。</p></li><li><p>在你的本地机器上将新远程仓库添加到你的本地仓库：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fork</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_git_usernam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/langflow.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>要在本地运行文档，请运行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>文档将在 <code>localhost:3000</code> 上可用，所有文件都位于 <code>docs/docs</code> 文件夹中。</p></li></ol><h2 id="打开一个拉取请求" tabindex="-1">打开一个拉取请求 <a class="header-anchor" href="#打开一个拉取请求" aria-label="Permalink to &quot;打开一个拉取请求&quot;">​</a></h2><p>一旦你编写并通过 <code>make lint</code> 和 <code>make unit_tests</code> 手动测试了你的更改，请打开一个拉取请求（Pull Request）将你的更改上游发送到主 Langflow 仓库。</p><ol><li>基于 <code>main</code> 分支在 GitHub 上通过你的补丁打开一个新的拉取请求。</li><li>确保 PR 标题遵循语义提交惯例。例如，功能是 <code>feat: add new feature</code>，修复是 <code>fix: correct issue with X</code>。</li><li>一名 Langflow 的维护者将审查你的拉取请求。感谢你的贡献！</li></ol><p>关于拉取请求标题的一些额外指导：</p><ul><li>确保拉取请求描述清楚地描述了问题和解决方案。如果 PR 修复了一个问题，请在 PR 描述中包含到修复问题的链接，使用 <code>Fixes #1234</code>。</li><li>拉取请求标题会出现在 Langflow 的发行说明中，所以它们应该尽可能明确地说明 PR 做了什么。</li><li>拉取请求应努力只修复一件事，并且应包含对所修复内容的详细描述。</li></ul><p>欲了解更多信息，请参阅 <a href="https://devguide.python.org/getting-started/pull-request-lifecycle/index.html#making-good-commits" target="_blank" rel="noreferrer">Python 开发者指南</a>。</p>`,33)]))}const k=e(n,[["render",t]]);export{g as __pageData,k as default};
